WITH flattened_attrs AS (SELECT id, plan, effective_from, tier_prices, SLICE(tier_limits, 1, 2) AS first_two_limits, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers) SELECT *, SUM(entry_price) OVER (PARTITION BY plan ORDER BY effective_from ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_entry_price, AVG(entry_price) OVER (ORDER BY entry_price ASC, id ASC ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS entry_price_avg_3_prior FROM flattened_attrs;
